<script setup lang="ts">import { characters } from '~/data/content'; const query=ref(''); const filtered=computed(()=>characters.filter(c=>`${c.hanzi}${c.pinyin}${c.meaning}`.toLowerCase().includes(query.value.toLowerCase()))); const speak=(t:string)=>speechSynthesis.speak(new SpeechSynthesisUtterance(t))</script>
<template><section><div class="page-title"><span class="eyebrow">BIBLIOTECA</span><h1>Dicionário de caracteres</h1><p class="muted">Explore os caracteres que formam seu caminho.</p></div><div class="toolbar"><input v-model="query" class="input" placeholder="Pesquisar por hanzi, pinyin ou significado…"><select class="select"><option>Todos os status</option><option>Não estudados</option><option>Dominados</option></select></div><div class="grid character-grid"><div v-for="c in filtered" :key="c.hanzi" class="card char-card"><div class="hanzi">{{c.hanzi}}</div><b>{{c.pinyin}}</b><small>{{c.meaning}}</small><div style="margin-top:12px"><span class="pill">{{c.status}}</span></div><button @click="speak(c.pinyin)" class="muted" style="background:none;border:0;margin-top:12px;cursor:pointer">🔊 Ouvir</button></div></div></section></template>
